#include <stdio.h>
#include <stdlib.h>
#include "ft_list.h"

void ft_list_foreach(t_list *begin_list, void (*f)(void *));

static t_list	*new_node(void *data, t_list *next)
{
	t_list	*node;

	node = malloc(sizeof(t_list));
	node->data = data;
	node->next = next;
	return (node);
}

static void	print_str(void *data)
{
	printf("%s\n", (char *)data);
}

int	main(void)
{
	t_list	*list;

	list = new_node("a", new_node("b", new_node("c", NULL)));
	ft_list_foreach(list, print_str);
	return (0);
}

